select distinct t.channel_code as channelCode,t.device_code as deviceCode,t.channel_name as channelName,o.tenant_id as tenantId
from vm_channel_info_t t
left join vm_order_devices o on t.device_code=o.device_code
where  o.delete_flag='0' and  t.device_code =#{deviceCode} and o.tenant_id=#{tenantId}
and t.channel_code = #{channelCode,jdbcType=VARCHAR}
